contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        require(recipient != address(c));
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        address ownerAfter = c.owner();
        assert(!reverted && ownerAfter == address(this) && address(c).balance == balBefore);
    }
    receive() external payable {}
}

